import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable, map } from 'rxjs';
import { TipoDocumentoMaestro, TipoDocumentoMaestroPayload, PaginatedTiposDocumentoMaestro } from '../models/tipo-documento-maestro.model';
import { environment } from '../../../environments/environment';

@Injectable({ providedIn: 'root' })
export class TipoDocumentoMaestroService {
  private readonly http = inject(HttpClient);
  private readonly baseUrl = `${environment.apiUrl}/tipos-documento-maestros`;

  getAll(page = 1): Observable<PaginatedTiposDocumentoMaestro> {
    const params = new HttpParams().set('page', page);
    return this.http.get<{ data: TipoDocumentoMaestro[], meta: { current_page: number, last_page: number, per_page: number, total: number } }>(this.baseUrl, { params }).pipe(
      map(response => ({
        data: response.data,
        current_page: response.meta.current_page,
        last_page: response.meta.last_page,
        per_page: response.meta.per_page,
        total: response.meta.total
      }))
    );
  }

  getById(id: number): Observable<TipoDocumentoMaestro> {
    return this.http.get<{ data: TipoDocumentoMaestro }>(`${this.baseUrl}/${id}`)
      .pipe(map(response => response.data));
  }

  private mapToRawPayload(payload: TipoDocumentoMaestroPayload) {
    return {
      nombre: payload.nombre,
      aliases: payload.aliases?.map(a => ({
        municipio_id: a.municipioId,
        alias: a.alias
      }))
    };
  }

  create(payload: TipoDocumentoMaestroPayload): Observable<TipoDocumentoMaestro> {
    return this.http.post<{ data: TipoDocumentoMaestro }>(this.baseUrl, this.mapToRawPayload(payload))
      .pipe(map(response => response.data));
  }

  update(id: number, payload: TipoDocumentoMaestroPayload): Observable<TipoDocumentoMaestro> {
    return this.http.put<{ data: TipoDocumentoMaestro }>(`${this.baseUrl}/${id}`, this.mapToRawPayload(payload))
      .pipe(map(response => response.data));
  }

  delete(id: number): Observable<void> {
    return this.http.delete<void>(`${this.baseUrl}/${id}`);
  }
}
